D = {"/": "-", "-": "|", "|": "/"}
P = {"/": "|", "-": "/", "|": "-"}          # cyclic predecessor


def solve(clue):
    """Rearrange the clue's strokes into a well-formed whole word.

    Counts (p, q, r) of / - | determine the multiset of nested pairs uniquely:
    a = #(/ -) pairs, b = #(- |), c = #(| /) with a+c = p, a+b = q, b+c = r.
    Any such multiset can be laid out as a tree in which a node of type t may only
    carry children of type t or P[t]; the word is then read off by nesting.
    The tree shape and child order are randomised (seeded by the clue) so demos do
    not show a canonical layout.
    """
    r = random.Random(clue)
    p, q, u = clue.count("/"), clue.count("-"), clue.count("|")
    a, b, c = p + q - u, q + u - p, u + p - q
    if min(a, b, c) < 0 or a % 2 or b % 2 or c % 2:
        return ""
    cnt = {"/": a // 2, "-": b // 2, "|": c // 2}
    root_t = None
    for t0 in "/-|":
        order = [t0, P[t0], P[P[t0]]]
        seq = [cnt[t] for t in order]
        if seq[0] == 0:
            continue
        zero = False
        good = True
        for v in seq:
            if v == 0:
                zero = True
            elif zero:
                good = False
        if good:
            root_t = t0
            break
    if root_t is None:
        return ""
    order = [root_t, P[root_t], P[P[root_t]]]
    typ = [root_t]
    kids = [[]]
    for gi in range(3):
        g = order[gi]
        prevs = order[gi - 1] if gi else None
        for j in range(cnt[g] - (1 if gi == 0 else 0)):
            cand = [i for i in range(len(typ)) if typ[i] == g or typ[i] == prevs]
            u2 = r.choice(cand)
            typ.append(g)
            kids.append([])
            kids[u2].insert(r.randint(0, len(kids[u2])), len(typ) - 1)

    def word(i):
        return typ[i] + "".join(word(j) for j in kids[i]) + D[typ[i]]

    return word(0)

